(function(){
  "use strict";

  // ---- Embedded CV as data URI (self-contained download) ----
  var CV_DATA_URI = "data:application/pdf;base64,";
  var dlBtn1 = document.getElementById('downloadCvBtn');
  var dlBtn2 = document.getElementById('downloadCvBtn2');
  if(dlBtn1){ dlBtn1.setAttribute('href', CV_DATA_URI); }
  if(dlBtn2){ dlBtn2.setAttribute('href', CV_DATA_URI); }

  // ---- Footer year ----
  var yearEl = document.getElementById('year');
  if(yearEl){ yearEl.textContent = new Date().getFullYear(); }

  // ---- Sticky nav shadow on scroll ----
  var nav = document.getElementById('siteNav');
  function onScroll(){
    if(window.scrollY > 8){ nav.classList.add('scrolled'); }
    else{ nav.classList.remove('scrolled'); }

    var backBtn = document.getElementById('backToTop');
    if(window.scrollY > 600){ backBtn.classList.add('show'); }
    else{ backBtn.classList.remove('show'); }
  }
  window.addEventListener('scroll', onScroll, { passive:true });
  onScroll();

  // ---- Mobile menu toggle ----
  var toggle = document.getElementById('navToggle');
  var menu = document.getElementById('mobileMenu');
  toggle.addEventListener('click', function(){
    var isOpen = menu.classList.toggle('open');
    toggle.classList.toggle('open', isOpen);
    toggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    document.body.style.overflow = isOpen ? 'hidden' : '';
  });
  menu.querySelectorAll('a').forEach(function(a){
    a.addEventListener('click', function(){
      menu.classList.remove('open');
      toggle.classList.remove('open');
      toggle.setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
    });
  });

  // ---- Back to top ----
  document.getElementById('backToTop').addEventListener('click', function(){
    window.scrollTo({ top:0, behavior:'smooth' });
  });

  // ---- Active nav link highlighting ----
  var sections = Array.prototype.slice.call(document.querySelectorAll('section[id]'));
  var navLinks = Array.prototype.slice.call(document.querySelectorAll('.nav-links a[data-nav]'));
  function updateActiveLink(){
    var scrollPos = window.scrollY + 120;
    var current = sections[0] ? sections[0].id : null;
    sections.forEach(function(sec){
      if(sec.offsetTop <= scrollPos){ current = sec.id; }
    });
    navLinks.forEach(function(link){
      var match = link.getAttribute('href') === '#' + current;
      link.classList.toggle('active', match);
    });
  }
  window.addEventListener('scroll', updateActiveLink, { passive:true });
  updateActiveLink();

  // ---- Scroll reveal animations ----
  var revealEls = Array.prototype.slice.call(document.querySelectorAll('.reveal, .reveal-stagger'));
  if('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(entry.isIntersecting){
          entry.target.classList.add('in');
          io.unobserve(entry.target);
        }
      });
    }, { threshold:0.12, rootMargin:'0px 0px -40px 0px' });
    revealEls.forEach(function(el){ io.observe(el); });
  } else {
    revealEls.forEach(function(el){ el.classList.add('in'); });
  }
})();
